  `content` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '提示内容',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_message_target_user_id`(`target_user_id` ASC) USING BTREE,
  INDEX `idx_user_message_sender_user_id`(`sender_user_id` ASC) USING BTREE,
  CONSTRAINT `fk_user_message_sender_user` FOREIGN KEY (`sender_user_id`) REFERENCES `user_account` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_user_message_target_user` FOREIGN KEY (`target_user_id`) REFERENCES `user_account` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 69 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用户信息提示表' ROW_FORMAT = DYNAMIC;

